<?php
require_once __DIR__.'/includes/bootstrap.php';
require_role(['client']);
$clientId=current_client_id();
if($clientId<1){http_response_code(403);exit('Compte client non associé.');}
$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    $action=(string)($_POST['action']??'');
    try{
        if($action==='request'){
            $type=(string)($_POST['type']??'');
            $date=(string)($_POST['date_prevue']??'');
            $slot=(string)($_POST['creneau']??'');
            $address=trim((string)($_POST['adresse']??''));
            $details=trim((string)($_POST['details']??''));
            $validDate=DateTime::createFromFormat('Y-m-d',$date);
            if(!in_array($type,['depot','ramassage'],true)||!in_array($slot,['matin','apres_midi','soir'],true)||!$validDate||$validDate->format('Y-m-d')!==$date||$date<date('Y-m-d')||($type==='ramassage'&&$address==='')||mb_strlen($details)>500)throw new RuntimeException('Vérifiez le type, la date, le créneau et l’adresse.');
            $pdo->prepare('INSERT INTO demandes_clients(client_id,type,date_prevue,creneau,adresse,details) VALUES(?,?,?,?,?,?)')->execute([$clientId,$type,$date,$slot,$address?:null,$details?:null]);
            flash('Votre demande a été envoyée.');
        }elseif($action==='rating'){
            $orderId=(int)($_POST['commande_id']??0);
            $rating=(int)($_POST['note']??0);
            $comment=trim((string)($_POST['commentaire']??''));
            if($rating<1||$rating>5||mb_strlen($comment)>1000)throw new RuntimeException('Choisissez une note de 1 à 5 étoiles.');
            $order=$pdo->prepare("SELECT id FROM commandes WHERE id=? AND client_id=? AND statut='retire'");
            $order->execute([$orderId,$clientId]);
            if(!$order->fetchColumn())throw new RuntimeException('Cette commande n’est pas disponible pour une évaluation.');
            $pdo->prepare('INSERT INTO avis_clients(client_id,commande_id,note,commentaire) VALUES(?,?,?,?)')->execute([$clientId,$orderId,$rating,$comment?:null]);
            flash('Merci pour votre évaluation.');
        }else{throw new RuntimeException('Action non autorisée.');}
    }catch(Throwable $e){flash($e instanceof RuntimeException?$e->getMessage():'Cette action n’a pas pu être enregistrée.','error');}
    redirect('client.php');
}
$clientQuery=$pdo->prepare('SELECT nom,prenom,email,telephone,adresse FROM clients WHERE id=? AND utilisateur_id=? AND supprime=0');
$clientQuery->execute([$clientId,(int)$_SESSION['user']['id']]);
$client=$clientQuery->fetch();
if(!$client){http_response_code(403);exit('Compte client non associé.');}
$requests=$pdo->prepare('SELECT type,date_prevue,creneau,adresse,statut,cree_le FROM demandes_clients WHERE client_id=? ORDER BY date_prevue DESC,id DESC LIMIT 20');
$requests->execute([$clientId]);$requests=$requests->fetchAll();
$orders=$pdo->prepare("SELECT o.id,o.reference,o.date_depot,o.total FROM commandes o WHERE o.client_id=? AND o.statut='retire' AND NOT EXISTS(SELECT 1 FROM avis_clients a WHERE a.client_id=o.client_id AND a.commande_id=o.id) ORDER BY o.id DESC LIMIT 20");
$orders->execute([$clientId]);$orders=$orders->fetchAll();
$ratings=$pdo->prepare('SELECT o.reference,a.note,a.commentaire,a.cree_le FROM avis_clients a JOIN commandes o ON o.id=a.commande_id WHERE a.client_id=? ORDER BY a.id DESC LIMIT 20');
$ratings->execute([$clientId]);$ratings=$ratings->fetchAll();
$messages=$pdo->prepare("SELECT m.canal,m.contenu,m.date_envoi,o.reference FROM communications m LEFT JOIN commandes o ON o.id=m.commande_id WHERE m.client_id=? AND m.sens='sortant' AND m.statut IN ('envoye','envoye_manuellement') ORDER BY COALESCE(m.date_envoi,m.cree_le) DESC LIMIT 50");
$messages->execute([$clientId]);$messages=$messages->fetchAll();
?><?php $language=$_SESSION['language']??'fr';?><!doctype html><html lang="<?=e($language)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>Espace client · Pressa</title><script>try{document.documentElement.dataset.theme=localStorage.getItem('pressa-theme')||'light'}catch(e){}</script><link rel="stylesheet" href="assets/css/style.css"></head><body class="client-portal"><header class="client-topbar"><a class="client-brand" href="client.php"><img src="assets/img/Pressa%20Dragon%20Steam%20Emblem.png" alt="Pressa"><span>Espace client</span></a><div><span><?=e(trim(($client['prenom']??'').' '.$client['nom']))?></span><label class="language-control" title="Langue"><span class="sr-only">Langue</span><select class="language-select client-language" id="languageSelect" aria-label="Langue"><option value="fr" <?=$language==='fr'?'selected':''?>>FR</option><option value="en" <?=$language==='en'?'selected':''?>>EN</option><option value="es" <?=$language==='es'?'selected':''?>>ES</option><option value="pt" <?=$language==='pt'?'selected':''?>>PT</option><option value="de" <?=$language==='de'?'selected':''?>>DE</option><option value="it" <?=$language==='it'?'selected':''?>>IT</option><option value="ar" <?=$language==='ar'?'selected':''?>>AR</option><option value="zh" <?=$language==='zh'?'selected':''?>>ZH</option><option value="ha" <?=$language==='ha'?'selected':''?>>HA</option></select></label><form action="logout.php" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button class="logout topbar-logout" type="submit">↪ Déconnexion</button></form></div></header>
<main class="client-main"><section class="client-welcome"><p class="eyebrow">PRESSA · ESPACE CLIENT</p><h1>Bonjour <?=e($client['prenom']?:$client['nom'])?></h1><p>Vos demandes, vos avis et les messages de Pressa, au même endroit.</p></section><?php if(!empty($_SESSION['flash'])):?><div class="alert <?=e($_SESSION['flash']['type'])?>"><?=e($_SESSION['flash']['message'])?></div><?php unset($_SESSION['flash']);endif;?>
<nav class="client-nav" aria-label="Espace client"><a href="#demandes">⌖ Dépôt ou ramassage</a><a href="#evaluations">★ Évaluer le service</a><a href="#messages">✉ Mes messages</a></nav>
<section class="panel client-section" id="demandes"><div class="panel-head"><div><p class="eyebrow">SERVICE</p><h2>Programmer un dépôt ou un ramassage</h2></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="request"><div class="field"><label for="requestType">Demande</label><select id="requestType" name="type"><option value="depot">Dépôt de vêtements</option><option value="ramassage">Ramassage à mon adresse</option></select></div><div class="field"><label for="requestDate">Date souhaitée</label><input id="requestDate" type="date" name="date_prevue" min="<?=date('Y-m-d')?>" required></div><div class="field"><label for="requestSlot">Créneau</label><select id="requestSlot" name="creneau"><option value="matin">Matin</option><option value="apres_midi">Après-midi</option><option value="soir">Soir</option></select></div><div class="field" id="pickupAddressField" hidden><label for="pickupAddress">Adresse de ramassage</label><input id="pickupAddress" name="adresse" value="<?=e($client['adresse']??'')?>" maxlength="255"></div><div class="field full"><label for="requestDetails">Précisions facultatives</label><textarea id="requestDetails" name="details" maxlength="500" rows="3"></textarea></div><div class="field full"><button class="btn">Envoyer la demande</button></div></form><div class="table-wrap"><table><thead><tr><th>Type</th><th>Date</th><th>Créneau</th><th>État</th></tr></thead><tbody><?php foreach($requests as $request):?><tr><td><?=e($request['type']==='depot'?'Dépôt':'Ramassage')?></td><td><?=e($request['date_prevue'])?></td><td><?=e(delivery_slot_label($request['creneau']))?></td><td><?=e(['en_attente'=>'En attente','confirmee'=>'Confirmée','refusee'=>'Refusée','terminee'=>'Terminée'][$request['statut']]??$request['statut'])?></td></tr><?php endforeach;?><?php if(!$requests):?><tr><td colspan="4" class="empty">Aucune demande enregistrée.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel client-section" id="evaluations"><p class="eyebrow">VOTRE AVIS</p><h2>Évaluer le service reçu</h2><?php foreach($orders as $order):?><form method="post" class="rating-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="rating"><input type="hidden" name="commande_id" value="<?=(int)$order['id']?>"><div><strong><?=e($order['reference'])?></strong><small> · <?=e($order['date_depot'])?></small></div><div class="field"><label for="rating<?=(int)$order['id']?>">Votre note</label><select id="rating<?=(int)$order['id']?>" name="note" required><option value="">Choisir une note</option><option value="5">★★★★★ · Excellent</option><option value="4">★★★★ · Très bien</option><option value="3">★★★ · Bien</option><option value="2">★★ · À améliorer</option><option value="1">★ · Insatisfaisant</option></select></div><div class="field"><label for="comment<?=(int)$order['id']?>">Commentaire facultatif</label><textarea id="comment<?=(int)$order['id']?>" name="commentaire" maxlength="1000" rows="2"></textarea></div><button class="btn">Envoyer mon avis</button></form><?php endforeach;?><?php if(!$orders):?><p class="empty">Aucune commande terminée à évaluer.</p><?php endif;?><?php foreach($ratings as $rating):?><div class="rating-receipt"><strong><?=e($rating['reference'])?></strong><span><?=str_repeat('★',(int)$rating['note'])?><?=str_repeat('☆',5-(int)$rating['note'])?></span><p><?=e($rating['commentaire']??'Merci pour votre avis.')?></p></div><?php endforeach;?></section>
<section class="panel client-section" id="messages"><p class="eyebrow">INFORMATIONS PRESSA</p><h2>Messages reçus</h2><?php foreach($messages as $message):?><article class="client-message"><div><strong><?=e(strtoupper($message['canal']))?></strong><span><?=e($message['date_envoi']??'')?></span></div><?php if(!empty($message['reference'])):?><small>Commande <?=e($message['reference'])?></small><?php endif;?><p><?=nl2br(e($message['contenu']))?></p></article><?php endforeach;?><?php if(!$messages):?><p class="empty">Vous n’avez pas encore reçu de message.</p><?php endif;?></section></main>
<script src="assets/js/app.js" defer></script><script src="assets/js/locales.js" defer></script><script src="assets/js/i18n.js" defer></script><script>const requestType=document.getElementById('requestType'),addressField=document.getElementById('pickupAddressField'),addressInput=document.getElementById('pickupAddress');function updateRequestType(){const pickup=requestType.value==='ramassage';addressField.hidden=!pickup;addressInput.required=pickup;}requestType.addEventListener('change',updateRequestType);updateRequestType();</script></body></html>
